import { readFileSync } from 'node:fs'

function fail(msg, code = 2) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail('error: usage: cli.js waves|explain|pack <workers>')
} else if (mode === 'pack' && args.length === 2) {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else if (mode === 'pack') {
  fail('error: usage: cli.js waves|explain|pack <workers>')
} else {
  fail('error: usage: cli.js waves|explain|pack <workers>')
}

const text = readFileSync(0, 'utf8')
const lines = text.split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cost = new Map()
const deps = new Map()
const depUses = []
lines.forEach((raw, i) => {
  const n = i + 1
  const line = raw.trim()
  if (line === '' || line.startsWith('#')) return
  const w = line.split(/\s+/)
  if (w[0] === 'task') {
    if (w.length !== 3) fail(`error: line ${n}: expected task <name> <cost>`)
    if (!/^[A-Za-z0-9_.-]+$/.test(w[1])) fail(`error: line ${n}: invalid task name ${w[1]}`)
    if (!/^[0-9]+$/.test(w[2])) fail(`error: line ${n}: cost must be a non-negative integer`)
    if (cost.has(w[1])) fail(`error: line ${n}: task ${w[1]} is declared twice`)
    cost.set(w[1], BigInt(w[2]))
  } else if (w[0] === 'dep') {
    if (w.length < 3) fail(`error: line ${n}: expected dep <name> <dependency>...`)
    for (const x of w.slice(1)) depUses.push(x)
    depUses.push(null)
    deps.set(n, w.slice(1))
  } else {
    fail(`error: line ${n}: unknown directive ${w[0]}`)
  }
})

const dmap = new Map()
for (const k of cost.keys()) dmap.set(k, new Set())
for (const x of depUses) if (x !== null && !cost.has(x)) fail(`error: unknown task ${x}`)
for (const [, w] of deps) for (const d of w.slice(1)) dmap.get(w[0]).add(d)

const names = [...cost.keys()].sort()
const sdeps = new Map(names.map((k) => [k, [...dmap.get(k)].sort()]))

// cycle detection
{
  const state = new Map()
  const stack = []
  const visit = (u) => {
    state.set(u, 1)
    stack.push(u)
    for (const v of sdeps.get(u)) {
      const s = state.get(v)
      if (s === 1) {
        const cyc = stack.slice(stack.indexOf(v)).concat(v)
        fail('error: cycle: ' + cyc.join(' -> '), 3)
      }
      if (!s) visit(v)
    }
    stack.pop()
    state.set(u, 2)
  }
  for (const k of names) if (!state.get(k)) visit(k)
}

const start = new Map()
const finish = new Map()
const depth = new Map()
const calc = (u) => {
  if (finish.has(u)) return
  let s = 0n
  let d = 0
  for (const v of sdeps.get(u)) {
    calc(v)
    if (finish.get(v) > s) s = finish.get(v)
    if (depth.get(v) + 1 > d) d = depth.get(v) + 1
  }
  start.set(u, s)
  finish.set(u, s + cost.get(u))
  depth.set(u, d)
}
for (const k of names) calc(k)
let total = 0n
for (const f of finish.values()) if (f > total) total = f

let out = ''
if (mode === 'waves') {
  const ws = []
  for (const k of names) (ws[depth.get(k)] ??= []).push(k)
  ws.forEach((w, i) => { out += `wave ${i}: ${w.join(' ')}\n` })
  out += `total ${total}\n`
} else if (mode === 'explain') {
  for (const k of names) out += `${k} start=${start.get(k)} finish=${finish.get(k)} depth=${depth.get(k)}\n`
  out += `total ${total}\n`
} else {
  const prio = new Map()
  const dependents = new Map(names.map((k) => [k, []]))
  for (const k of names) for (const v of sdeps.get(k)) dependents.get(v).push(k)
  const pr = (u) => {
    if (prio.has(u)) return prio.get(u)
    let m = 0n
    for (const x of dependents.get(u)) { const p = pr(x); if (p > m) m = p }
    prio.set(u, m + cost.get(u))
    return prio.get(u)
  }
  for (const k of names) pr(k)
  const order = [...names].sort((a, b) => (prio.get(a) === prio.get(b) ? 0 : prio.get(a) > prio.get(b) ? -1 : 1) || (a < b ? -1 : a > b ? 1 : 0))
  const done = new Map() // name -> finish
  const freeAt = Array(workers).fill(0n)
  const runs = Array.from({ length: workers }, () => [])
  let t = 0n
  let remaining = names.length
  while (remaining > 0) {
    for (;;) {
      const wi = freeAt.findIndex((f) => f <= t)
      if (wi < 0) break
      const task = order.find((u) => !done.has(u) && sdeps.get(u).every((d) => done.has(d) && done.get(d) <= t))
      if (task === undefined) break
      const f = t + cost.get(task)
      done.set(task, f)
      freeAt[wi] = f
      runs[wi].push(`${task}@${t}-${f}`)
      remaining--
    }
    if (remaining === 0) break
    let next = null
    for (const f of freeAt) if (f > t && (next === null || f < next)) next = f
    t = next
  }
  runs.forEach((r, i) => { out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n` })
  out += `makespan ${total}\n`
}
process.stdout.write(out)
EOF
